  "Eşleşme eşiği": "Порог совпадения", "Kosinüs benzerliği × 100. 45 önerilir; düşük = daha hoşgörülü (yanlış kabul riski), yüksek = daha sıkı (ışık değişiminde ret).": "Косинусное сходство × 100. Рекомендуется 45; ниже = мягче (риск ложного принятия), выше = строже (отказы при смене освещения).",
