  "Henüz kayıtlı parametre yok. Sanal dronla uçarken HEPGO panelinden ya da Mission Planner'dan değiştirilen her parametre burada kalıcı olur; aynı dronla SITL yeniden açılınca geri yüklenir.": "Сохранённых параметров пока нет. Каждый параметр, изменённый с панели HEPGO или из Mission Planner во время полёта виртуального дрона, сохраняется здесь и восстанавливается при перезапуске SITL с тем же дроном.",
  "Kaydedilmeyenler (oturum/simülatör ayarı ya da sayaç): {prefixes} ön ekleri ve {names}": "Не сохраняются (настройки сеанса/симулятора или счётчики): префиксы {prefixes} и {names}",
