  "Motor ve batarya bütçesi: azami hız SITL fiziğine ve ArduPilot hız sınırlarına uygulanır; yakıt mesafe + gaz koluna, elektronik batarya saatlik tüketime göre azalır. Biterse yalnız kırmızı uyarı verilir, uçuş sürer. Uçuş sonunda ölçülen km/L ve ortalama W dron kaydına yazılır ve sonraki simülasyonda önerilir.": "Бюджет двигателя и батареи: максимальная скорость применяется к физике SITL и ограничениям скорости ArduPilot; топливо убывает с расстоянием + газом, батарея электроники — по часовому потреблению. При исчерпании выводится только красное предупреждение, полёт продолжается. В конце измеренные км/л и средние Вт записываются в карточку дрона и предлагаются в следующей симуляции.",
  "Motor": "Двигатель",
  "Azami hız": "Максимальная скорость",
  "Tam gazda seviye uçuş hızı (CAYMAZ 222 cc karbüratörlü motor: 45 m/s). SITL itki çarpanı + AIRSPEED_MAX/CRUISE, THR_MAX 100.": "Скорость горизонтального полёта на полном газу (CAYMAZ карбюраторный двигатель 222 см³: 45 м/с). Множитель тяги SITL + AIRSPEED_MAX/CRUISE, THR_MAX 100.",
  "Yakıt": "Топливо",
  "0 = yakıt göstergesi yok (elektrikli).": "0 = без указателя топлива (электрический).",
  "Tüketim": "Расход",
  "Seyirde kat edilen km başına yakıt; gaz kolu %100'de tüketim 2 katına çıkar.": "Топливо на км крейсерского полёта; при 100 % газа расход удваивается.",
  "Elektronik batarya": "Батарея электроники",
