  "Otopilot, telemetri, servolar (servo hareketi küçük ek yük); SITL'in kendi pil göstergesi değildir.": "Автопилот, телеметрия, сервоприводы (движение сервоприводов — небольшая добавка); это не указатель батареи SITL.",
