  "Yakıt menzili ≈ {r} (seyir)": "Запас хода по топливу ≈ {r} (крейсер)",
  "Yakıt göstergesi kapalı": "Указатель топлива выключен",
  "Batarya {wh} Wh ≈ {m}": "Батарея {wh} Вт·ч ≈ {m}",
  "Batarya göstergesi kapalı": "Указатель батареи выключен",
  "SITL ikilisi itki ölçeği (SIM_PLN_THR_MUL) desteklemiyor: azami hız yalnız ArduPilot sınırlarına uygulanır; tam gaz hızı stok fizikte ≈ {s} m/s kalır.": "Двоичный файл SITL не поддерживает масштаб тяги (SIM_PLN_THR_MUL): максимальная скорость применяется только к ограничениям ArduPilot; на полном газу скорость остаётся ≈ {s} м/с в стандартной физике.",
