  // --- Uçuş Simülatörü §13.1: kontrol düzeni (klasik / elevon / V-kuyruk) ---
  "Aileron + Elevatör (T-kuyruk)": "Элероны + руль высоты (Т-хвост)",
  "Elevon (delta kanat)": "Элевоны (дельта-крыло)",
  "V-kuyruk (ruddervator)": "V-образный хвост (руддерватор)",
  "Klasik": "Классика",
  "Elevon": "Элевоны",
  "V-kuyruk": "V-хвост",
  "Kontrol düzeni": "Схема управления",
  "Düzen": "Схема",
  "Düzen sütunu": "Столбец «Схема»",
  "Önerilen": "Рекомендуется",
  "SITL modeli": "Модель SITL",
  "kalıcı kayıt öncelikli": "приоритет у сохранённой записи",
  "Klasik kuyruk: kanat uçlarında aileron (yatış), yatay kuyrukta elevatör (yunuslama), dikey kuyrukta rudder (sapma). SERVO1 4 · SERVO2 19 · SERVO4 21.": "Классический хвост: элероны на крыле (крен), руль высоты (тангаж), руль направления (рыскание). SERVO1 4 · SERVO2 19 · SERVO4 21.",
  "Delta / uçan kanat: iki elevon hem yunuslama hem yatış (ArduPlane karışımı, MIXING_GAIN). SERVO1 78 · SERVO2 77 (REVERSED 1/1); SITL plane-elevon.": "Дельта / летающее крыло: два элевона для тангажа и крена (микшер ArduPlane, MIXING_GAIN). SERVO1 78 · SERVO2 77 (REVERSED 1/1); SITL plane-elevon.",
  "V-kuyruk: iki ruddervator hem yunuslama hem sapma; kanatta aileron. SERVO1 4 · SERVO2 80 · SERVO4 79 (SERVO2 REVERSED 1); SITL plane-vtail.": "V-хвост: два руддерватора для тангажа и рыскания; элероны на крыле. SERVO1 4 · SERVO2 80 · SERVO4 79 (SERVO2 REVERSED 1); SITL plane-vtail.",
  "Kontrol yüzeylerinin düzeni: ArduPlane SERVO işlevleri ve SITL uçak modeli buna göre kurulur, 3B'de yüzeyler buna göre oynar. Model seçilince modelin düzeni önerilir; değiştirebilirsiniz.": "Схема рулевых поверхностей: по ней задаются функции SERVO ArduPlane и модель SITL, в 3D поверхности движутся соответственно. При выборе модели предлагается её схема; её можно изменить.",
  "CAYMAZ delta kanat: iki elevon hem yunuslama hem yatış; ArduPlane karışımı MIXING_GAIN 0,5 (doymaz). Dronun kalıcı kaydında SERVO1/2_FUNCTION varsa (ör. CAYMAZ 4/19) kalıcı değer öncelikli; SITL modeli etkin işlevlerden seçilir ve konsola yazılır.": "Дельта-крыло CAYMAZ: два элевона для тангажа и крена; микшер ArduPlane MIXING_GAIN 0,5 (без насыщения). Если в сохранённой записи дрона есть SERVO1/2_FUNCTION (напр. CAYMAZ 4/19), приоритет у неё; модель SITL выбирается по действующим функциям и пишется в консоль.",
  "V-kuyruk: sağa sapma komutunda sol ruddervator arka kenarı yukarı, sağ aşağı; burun yukarı komutunda ikisi de yukarı. ArduPilot'un kendi SITL kurulumu (plane-vtail.parm) ile aynı.": "V-хвост: при команде рыскания вправо задняя кромка левого руддерватора идёт вверх, правого — вниз; при «нос вверх» обе вверх. Как в собственной настройке SITL ArduPilot (plane-vtail.parm).",
  "Klasik: aileron yatış, elevatör yunuslama, rudder sapma. ArduPlane varsayılan işlevleri.": "Классика: элероны — крен, руль высоты — тангаж, руль направления — рыскание. Функции ArduPlane по умолчанию.",
