  "Maskot sesli": "Звуки талисмана",
  "Maskot arada bir kendi sesini çıkarır (kedi miyavlar, robot bip-bop yapar…). Her karakterin sesini kutucuğundaki hoparlör düğmesiyle dinleyebilirsiniz.": "Талисман время от времени издаёт свой звук (кот мяукает, робот пищит…). Звук каждого персонажа можно послушать кнопкой динамика на его карточке.",
