  "Mesai: {s}. Bu saatler dışında, hafta sonu ve tatillerde tüm gün kapalı kalırsınız.": "Рабочее время: {s}. Вне этих часов, а также весь день в выходные и праздники вы недоступны.",
  "Kendinizi aramalara ve/veya mesajlara kapatabilirsiniz. Süre seçebilir, sürekli kapalı kalabilir ya da yalnız mesai sonrasında kapanabilirsiniz; süre dolunca otomatik açılır.": "Вы можете закрыться от звонков и/или сообщений: на время, постоянно или только после работы; по истечении срока всё откроется автоматически.",
  "“Sürekli”: siz açana kadar · “Mesai sonrası”: mesai bitiminden ertesi mesai başlangıcına, hafta sonu tüm gün": "«Постоянно»: пока вы не отключите · «После работы»: от конца рабочего дня до начала следующего, в выходные весь день",
  "⚠ {who} bağlantısının süresi doldu ya da izin geri alındı. Yeniden bağlamak için “Yeniden bağlan” düğmesine basın.": "⚠ Подключение {who} истекло или доступ отозван. Нажмите «Переподключить», чтобы подключить снова.",
