  "Gimbal ve FPV kameralarının görüntü türü; PiP penceresi de bu türle gösterir. Uçuş içinde T ile değiştirilebilir (Shift+T: termal paleti).": "Тип изображения камер подвеса и FPV; окно PiP тоже его использует. В полёте меняется клавишей T (Shift+T: тепловая палитра).",
  "Gimbal ve FPV kameralarının görüntü türü. Kayıt bu simülatörde yapıldıysa kaydın kamera türü kullanılır; uçuş içinde T ile değiştirilebilir.": "Тип изображения камер подвеса и FPV. Если запись сделана в этом симуляторе, используется её тип камеры; в полёте меняется клавишей T.",
