  "Simülasyonda havada sürekli uçan hedefler: her biri seçtiğiniz irtifada, verdiğiniz çapta dairesel yörüngede uçar (SITL'siz, sunucuda kinematik; Mission Planner haritasında ADSB trafiği olarak görünür). Dronunuz bir hedefe önleme yarıçapı içinde yaklaşınca \"önleme\" sayılır; raporda sayı ve süre yer alır.": "Цели, постоянно летающие в симуляции: каждая летит по круговой орбите на заданной высоте и диаметре (без SITL, кинематика на сервере; видны как ADSB-трафик на карте Mission Planner). Вход дрона в радиус перехвата засчитывается как «перехват»; в отчёте — число и время.",
