  "Dikey kalkış: GUIDED + ARM + VTOL kalkışı — kuyruk üstünden dikey tırmanır, hedef irtifada askıda bekler. Yatay uçuşa geçmek için FBWA / CRUISE / AUTO; dönüş RTL (dikey iniş).": "Вертикальный взлёт: GUIDED + ARM + VTOL-взлёт — набирает высоту с хвоста и зависает на заданной высоте. Для горизонтального полёта — FBWA / CRUISE / AUTO; возврат RTL (вертикальная посадка).",
