  "Kalkış noktasının yanında yer kontrol istasyonu ve Elektro-Optik + radar taşıyan kule. Radar 360° sürekli döner; EO seçilen hedefi izler.": "Наземный пункт управления рядом с точкой взлёта и вышка с оптико-электронной системой и радаром. Радар непрерывно вращается на 360°; ОЭС сопровождает выбранную цель.",
