  "Tamamen manuel uçuş. İstasyonun yanında rafta interceptor'lar hazır; dalgalar hâlinde rastgele mesafe ve yükseklikten gelen hedefler istasyona dalar. Interceptor'ı fırlat, kumandayla önle; önlenemeyen hedef istasyona çarparsa istasyon hasar alır.": "Полностью ручной полёт. Рядом с пунктом на стойке стоят перехватчики; волнами с произвольной дальности и высоты цели пикируют на пункт. Запусти перехватчик и останови их вручную; не перехваченная цель при попадании повреждает пункт.",
