  "Kutu fırlatıcı, 2×2 dikey hücre. Kapak açılır, interceptor kuyruk üstünden dikey çıkar; dolu/boş hücreler LED ve sayaçta.": "Контейнерная пусковая, 2×2 вертикальные ячейки. Крышка открывается, перехватчик выходит вертикально на хвосте; полные/пустые ячейки — светодиоды и счётчик.",
  "Kutu fırlatıcı, 4×2 dikey hücre. Görevde envanter kutulara dağılır (raf yerine).": "Контейнерная пусковая, 4×2 вертикальные ячейки. В задании запас распределяется по контейнерам (вместо стеллажа).",
  "Üç ayaklı sehpada tek dikey fırlatma tüpü; kapak açılır, interceptor tüpten çıkar.": "Одиночная вертикальная пусковая труба на треноге; крышка открывается, перехватчик выходит из трубы.",
  "Pilotun omzundaki silah benzeri aparat; üstündeki küçük ekranda göğe bakan kamera ve havadaki hedefler. Nişan alıp fırlatın.": "Похожее на оружие устройство на плече пилота; на маленьком экране — камера, смотрящая в небо, и воздушные цели. Прицельтесь и запустите.",
  "Dolu hücre": "Заряженные ячейки",
  "Nişan yönü": "Азимут прицеливания",
  "Nişan açısı": "Угол прицеливания",
  "Nişangâh": "Прицел",
  "\"Yer kontrolünü koru\" görevinde dolu hücre görevin interceptor sayısıdır: ⌈sayı / 4⌉ kutu yan yana kurulur (10'lu raf yerine).": "В задании «Защитить наземный пункт» заряженные ячейки = число перехватчиков задания: ⌈число / 4⌉ контейнеров рядом (вместо стеллажа на 10).",
  "\"Yer kontrolünü koru\" görevinde dolu hücre görevin interceptor sayısıdır: ⌈sayı / 8⌉ kutu yan yana kurulur (10'lu raf yerine).": "В задании «Защитить наземный пункт» заряженные ячейки = число перехватчиков задания: ⌈число / 8⌉ контейнеров рядом (вместо стеллажа на 10).",
  "Görevde 10'lu raf yedek deposudur; her \"sıradaki interceptor\" tüpe yeniden yüklenir.": "В задании стеллаж на 10 — запас; каждый «следующий перехватчик» заново заряжается в трубу.",
  "Uçuşta \"Nişangâh\" penceresi: aparatın baktığı yöne (göğe) kamera ve hedefler; fare sürükleme, I/J/K/L ya da ok düğmeleriyle nişan alın, \"Fırlat\" ile interceptor nişan yönünde çıkar.": "В полёте окно «Прицел» показывает камеру по направлению устройства (в небо) и цели; целиться мышью, I/J/K/L или стрелками; «Пуск» отправляет перехватчик по прицелу.",
  "INTERCEPTOR'ın hangi fırlatıcıdan çıkacağı: 4'lü ya da 8'li kutu fırlatıcı, yerden tekli tüp veya pilotun elindeki el fırlatıcısı. Tailsitter kuyruk üstünden dikey çıkar (SITL: GUIDED + NAV_TAKEOFF); el fırlatıcısında nişan yönüne yönelir.": "Из какой пусковой выходит INTERCEPTOR: 4- или 8-ячеечный контейнер, одиночная наземная труба или ручная пусковая пилота. Тейлситтер взлетает вертикально на хвосте (SITL: GUIDED + NAV_TAKEOFF); с ручной пусковой поворачивает по прицелу.",
  "Kayıttaki INTERCEPTOR'ın fırlatıcısı 3B sahnede kurulur (kayıt bu simülatörden ise kayıttaki fırlatıcı önerilir); ARM, fırlatma ve çıkış aşamaları logdan türetilir.": "Пусковая записанного INTERCEPTOR строится в 3D-сцене (если запись из этого симулятора, предлагается её пусковая); фазы ARM, пуска и выхода выводятся из лога.",
  "{c} hücreli kutu: {n} dolu · {e} boş. Kapak açılır, interceptor kuyruk üstünden dikey çıkar (SITL: GUIDED + ARM + NAV_TAKEOFF); hücre sırası soldan sağa, arka sıradan öne.": "Контейнер на {c} ячеек: {n} заряжено · {e} пусто. Крышка открывается, перехватчик взлетает вертикально (SITL: GUIDED + ARM + NAV_TAKEOFF); порядок ячеек слева направо, с заднего ряда.",
  "Yerden tekli tüp: kapak açılır, interceptor tüpten dikey çıkar (SITL: GUIDED + ARM + NAV_TAKEOFF).": "Одиночная наземная труба: крышка открывается, перехватчик выходит вертикально (SITL: GUIDED + ARM + NAV_TAKEOFF).",
  "El fırlatıcısı: nişan yönü {az}° · açısı {el}°. Fırlatınca interceptor 8 m dikey çıkar ve nişan doğrultusundaki noktaya ({h} m ileride, {a} m irtifa) yönelir. Uçuşta \"Nişangâh\" ile yeniden nişan alınabilir.": "Ручная пусковая: азимут {az}° · угол {el}°. При пуске перехватчик поднимается на 8 м и идёт к точке на линии прицела ({h} м вперёд, {a} м высоты). В полёте можно перенацелить в «Прицеле».",
  "El fırlatıcısı: GUIDED + ARM; interceptor tüpten çıkar, 8 m dikey tırmanır ve nişan doğrultusuna (az {az}° · el {el}° → {h} m ileride {a} m) yönelir (DO_REPOSITION). Hedef irtifa yok sayılır.": "Ручная пусковая: GUIDED + ARM; перехватчик выходит из трубы, поднимается на 8 м и поворачивает по прицелу (аз {az}° · угол {el}° → {h} м вперёд на {a} м) (DO_REPOSITION). Целевая высота не учитывается.",
  "Fırlatıcı: GUIDED + ARM; kapak açılır, interceptor kuyruk üstünden dikey çıkar (NAV_TAKEOFF) ve hedef irtifada askıda bekler. Yatay uçuş için FBWA / CRUISE / AUTO.": "Пусковая: GUIDED + ARM; крышка открывается, перехватчик взлетает вертикально (NAV_TAKEOFF) и зависает на заданной высоте. Горизонтальный полёт: FBWA / CRUISE / AUTO.",
  "El fırlatıcısı: GUIDED + ARM; interceptor tüpten çıkar ve nişan doğrultusuna yönelir (Nişangâh penceresindeki nişan).": "Ручная пусковая: GUIDED + ARM; перехватчик выходит из трубы и идёт по прицелу (окно «Прицел»).",
  "Fırlatıcı: GUIDED + ARM; kapak açılır, interceptor kuyruk üstünden dikey çıkar (NAV_TAKEOFF).": "Пусковая: GUIDED + ARM; крышка открывается, перехватчик взлетает вертикально (NAV_TAKEOFF).",
  "Interceptor fırlatıcıda, motor hazır": "Перехватчик в пусковой, моторы готовы",
