  "\"+ Yeni\" ile sihirbazı açın; \"Uç\" ile yapılan uçuşlar burada görünür.": "Откройте мастер кнопкой «+ Новый»; полёты, начатые кнопкой «Лететь», появятся здесь.",
  "\"Başlat\" ile bu ayarlarla uçun; uçuş bitince kaydı burada görünür.": "Летите с этими настройками кнопкой «Запустить»; запись появится здесь после полёта.",
  "\"{n}\" silinsin mi? Bu ayarlarla yapılmış uçuş kayıtları silinmez; Serbest Uçuş altında görünmeye devam eder.": "Удалить «{n}»? Записи полётов с этими настройками сохранятся и останутся в разделе «Свободный полёт».",
