  "Seyir {c} km/h (azami {m} km/h), gaz %{g}. Yakıt: L × km/L, gaz koluna göre; batarya: Wh ÷ saatlik W (servo ek yükü hariç). Uçuştaki göstergelerle aynı model.": "Крейсерская {c} км/ч (макс. {m} км/ч), газ {g}%. Топливо: Л × км/Л с учётом газа; батарея: Вт·ч ÷ часовая мощность Вт (без нагрузки сервоприводов). Та же модель, что и у приборов в полёте.",
