  "{n} yazıcının MAC adresi öğrenildi": "MAC-адрес получен для {n} принтеров",
  "Tüm ağ bloğunu tarar: yeni yazıcıları ekler, IP’si değişen kayıtlı yazıcıların IP’sini düzeltir (yazıcı MAC adresinden tanınır), MAC’i eksik yazıcıların MAC’ini öğrenir": "Сканирует весь сетевой блок: добавляет новые принтеры, исправляет IP зарегистрированных принтеров, у которых он изменился (принтер распознаётся по MAC), и получает недостающие MAC",
