  "MAC yok": "Нет MAC",
  "Yazıcıyı MAC ile bul: son görülen IP’de doğrular, değilse ağı tarayıp güncel IP’yi kaydeder": "Найти принтер по MAC: проверяет последний IP, иначе сканирует сеть и сохраняет текущий IP",
  "MAC ile Bul": "Найти по MAC",
  "Yazıcı yeni IP’de bulundu: {old} → {ip}": "Принтер найден по новому IP: {old} → {ip}",
  "MAC doğrulandı · IP {ip}": "MAC подтверждён · IP {ip}",
  "doğrulandı {at}": "проверен {at}",
  "MAC adresi (kablolu) — benzersiz kimlik": "MAC-адрес (проводной) — уникальный идентификатор",
  "Son görülen IP (isteğe bağlı)": "Последний IP (необязательно)",
  "MAC, yazıcının benzersiz kimliğidir; IP (DHCP) değişebilir. Dosya gönderilirken yazıcı MAC ile doğrulanır, IP’si değiştiyse ağ taranıp güncel IP bulunur. MAC’i boş bırakırsanız kayıttan sonra “MAC’i Öğren” ile cihazdan okuyun.": "MAC — уникальный идентификатор принтера; IP (DHCP) может меняться. При отправке файла принтер проверяется по MAC; если IP изменился, сеть сканируется для поиска текущего IP. Если оставить MAC пустым, считайте его с устройства кнопкой «Получить MAC» после сохранения.",
  "MAC yok — gönderilemez · {ip}": "Нет MAC — отправка невозможна · {ip}",
