  "Sol": "Слева",
  "Sağ": "Справа",
  "{n} yazıcının MAC adresi yok — bu yazıcılara dosya gönderilemez. Yazıcı Yönetimi’nde “MAC’i Öğren” ile kaydedin: {names}": "У {n} принтеров нет MAC-адреса — отправка файлов на них невозможна. Сохраните его в «Управлении принтерами» кнопкой «Получить MAC»: {names}",
  // §8.5 kayıttan oynatma girişleri (kaydı doğrudan izle · yalnız simülatör kayıtları · Simüle et)
  "Kaydedilen ayarlarla doğrudan izle": "Смотреть сразу с сохранёнными настройками",
  "Her oturumun kapanışında: özet rapor, .bin uçuş logu ve ekran kaydı. Oynat, kaydı kaydedilen ayarlarıyla (hava, rampa, kamera…) doğrudan izlemeye açar.": "При закрытии каждого сеанса: сводный отчёт, полётный журнал .bin и запись экрана. «Воспроизвести» сразу открывает запись с её сохранёнными настройками (погода, рампа, камера…).",
  "Bu kaydı oynatma yetkiniz yok": "У вас нет прав на воспроизведение этой записи",
  "Simülasyon kaydı bulunamadı": "Запись симуляции не найдена",
  "Kayıt kaydedilen ayarlarla açıldı": "Запись открыта с сохранёнными настройками",
  "{n} simülasyon kaydı": "Записей симуляции: {n}",
  "Uçuş logu bulunamadı ya da erişim yetkiniz yok (analizi tamamlanmış .bin / .log / .tlog gerekir).": "Полётный журнал не найден или нет доступа (нужен проанализированный .bin / .log / .tlog).",
  "Henüz oynatılabilir simülasyon kaydı yok. Canlı simülasyonda \"Uçuş logu (.bin)\" seçeneği açıkken uçun; kayıt kapanışta burada listelenir. Gerçek uçuşları ": "Пока нет воспроизводимых записей симуляции. Летайте в живой симуляции с включённым параметром «Полётный журнал (.bin)»; запись появится здесь после закрытия. Реальные полёты открывайте кнопкой «Симулировать» в разделе ",
  " ya da ": " или ",
  " ekranındaki \"Simüle et\" ile açın.": ".",
  "Seçilen uçuş kaydı 3B dünyada aynen oynatılır; kontrol sizde değildir. Atmosfer (dünya, saat, hava, rüzgâr), kalkış/rampa ve kamera sonraki adımlarda seçilir.": "Выбранный полётный журнал точно воспроизводится в 3D-мире; управление не у вас. Атмосфера (мир, время, погода, ветер), взлёт/рампа и камера выбираются на следующих шагах.",
  "Simülatörde kaydedilmiş uçuşlardan biri 3B dünyada aynen oynatılır; kontrol sizde değildir. Dünyanın merkezi kaydın kalkış (ilk ARM) noktasıdır. Saha görevlerinin gerçek uçuş logları burada listelenmez — Saha Yönetimi'nde uçuşun yanındaki \"Simüle et\" ile açılır.": "Один из полётов, записанных в симуляторе, точно воспроизводится в 3D-мире; управление не у вас. Центр мира — точка взлёта (первый ARM). Реальные журналы полевых заданий здесь не показываются — откройте их кнопкой «Симулировать» рядом с полётом в разделе «Полевые работы».",
  "Simüle et": "Симулировать",
  "Seçilen uçuş kaydı oynatılacak: atmosferi (dünya, saat, hava, rüzgâr), kalkışı/rampayı ve kamerayı seçin.": "Будет воспроизведён выбранный полётный журнал: выберите атмосферу (мир, время, погода, ветер), взлёт/рампу и камеру.",
  "Uçuşu simüle et": "Симулировать полёт",
  "Uçuş logu bulunamadı ya da erişim yetkiniz yok.": "Полётный журнал не найден или нет доступа.",
  "Uçuş Simülatörü'nde bu logu oynat: dünya, hava, rampa ve kamera sorulur": "Воспроизвести этот журнал в симуляторе полёта: будут запрошены мир, погода, рампа и камера",
  // §34 servo tetik
