  "Havada farklı yüksekliklerde numaralı halkalar kurulur; herkes aynı halkaları 1’den başlayarak sırayla ve ok yönünde geçmeye çalışır. Tüm halkaları ilk bitiren kazanır ve karşılaşma biter.": "В воздухе на разных высотах устанавливаются пронумерованные кольца; все стараются пролететь одни и те же кольца по порядку, начиная с 1, по направлению стрелки. Первый, кто пройдёт все кольца, побеждает, и матч заканчивается.",
