  "Henüz karşılaşma yok.": "Матчей пока нет.",
  "\"Yeni Karşılaşma\" ile halka yarışı kurun ve kullanıcıları davet edin.": "Создайте гонку по кольцам кнопкой «Новый матч» и пригласите пользователей.",
  "Sahte veri kipinde karşılaşma yok.": "В режиме тестовых данных матчей нет.",
  "Çok oyunculu halka yarışı: kullanıcıları davet edin, herkes gelince başlar": "Многопользовательская гонка по кольцам: пригласите пользователей; старт, когда соберутся все",
  "Çok oyunculu halka yarışı: Yeni Simülasyon ile aynı ayarlar; radar, elektro-optik ve yer kontrol yok. Sonunda kullanıcıları davet edip başlatın.": "Многопользовательская гонка по кольцам: те же настройки, что и в «Новой симуляции», без радара, оптико-электронной системы и наземного контроля. В конце пригласите пользователей и начните.",
  "Başlat’a basınca bekleme salonu açılır ve davet edilenlere bildirim gider. Herkes salona gelince her oyuncuya aynı dünyada farklı bir başlangıç noktasında simülatör açılır; geri sayımdan sonra kalkış serbesttir. Tüm halkaları ilk geçen kazanır.": "По нажатию «Начать» открывается зал ожидания и приглашённые получают уведомление. Когда все соберутся, каждому игроку открывается симулятор в том же мире в своей точке старта; после обратного отсчёта взлёт разрешён. Побеждает первый, кто пройдёт все кольца.",
  "Karşılaşmayı oluştur: bekleme salonu açılır, davetlilere bildirim gider": "Создать матч: откроется зал ожидания, приглашённые получат уведомление",
