  "Bu görev için seçilmiş kamera yok. Dron Yönetimi › Kameralar'da tanımlı kameralardan ekleyin.": "Для этого задания камеры не выбраны. Добавьте камеры из раздела Управление дронами › Камеры.",
  "Bu görevin kameraları: seç, köprü ve dron bağla, pencerede aç": "Камеры задания: выбрать, привязать мост и дрон, открыть в окне",
  "Bu köprü görüntü yeteneği bildirdi; ayarlar kaydedilince köprüye gönderilir.": "Мост сообщил о поддержке видео; настройки отправляются на мост при сохранении.",
  "Bu köprü görüntü yeteneği bildirmedi (Linux/Jetson köprüsü gerekir)": "Мост не сообщил о поддержке видео (нужен мост Linux/Jetson)",
  "Bu köprü görüntü yeteneği bildirmedi (Windows köprüsü). Linux / Jetson köprüsünü kurun; Dron Köprüleri sayfasından indirilebilir.": "Мост не сообщил о поддержке видео (мост Windows). Установите мост Linux / Jetson; его можно скачать на странице «Мосты дронов».",
  "Bu tarayıcı canlı akışı (MSE) oynatamıyor; JPEG anlık görüntü gösteriliyor.": "Браузер не может воспроизвести поток (MSE); показываются снимки JPEG.",
  "Dinleme portu (köprüde UDP)": "Порт приёма (UDP на мосту)",
  "Dron paneli ve Canlı Uçuş penceresinde bu dronun telemetrisi HUD'da gösterilir.": "Телеметрия этого дрона показывается в HUD на панели дрона и в окне «Живой полёт».",
  "Dron seçilmedi": "Дрон не выбран",
  "Düşük bant: yalnız 2 sn'de bir anlık görüntü (JPEG)": "Низкая полоса: только снимок (JPEG) раз в 2 с",
