  "Görüntü": "Видео",
  "Görüntü bağlantısı açık (/ws/drone/video)": "Видеосоединение открыто (/ws/drone/video)",
  "Görüntü köprüden canlı gelir; ■ Durdur ya da pencereyi kapatınca köprü yayını hemen durdurur. Gecikme sol altta gösterilir; \"JPEG\" düşük bant kipine geçer.": "Изображение поступает с моста в реальном времени; ■ Стоп или закрытие окна сразу останавливает поток. Задержка показана слева внизу; «JPEG» включает режим низкой пропускной способности.",
  "Durduruldu": "Остановлено",
  "Görüntü köprüsü": "Видеомост",
  "Görüntü köprüsü (şu an görüntü bağlantısı yok)": "Видеомост (сейчас нет видеосоединения)",
  "Görüntü yeteneği yok": "Нет поддержки видео",
  "Görüntüyü taşıyacak köprü: dronun kamerasıyla aynı ağdaki köprü (ör. dron üzerindeki Jetson).": "Мост для видео: мост в одной сети с камерой дрона (например, Jetson на дроне).",
  "H.265 (tarayıcı desteği sınırlı)": "H.265 (ограниченная поддержка браузеров)",
  "H.265 kaynak": "Источник H.265",
  "H.265 çoğu tarayıcıda oynatılamaz: kaynakta H.264 seçin ya da köprü ayarında h265 = yeniden_kodla (Jetson donanım kodlayıcıyla).": "Большинство браузеров не воспроизводят H.265: выберите H.264 на источнике или h265 = yeniden_kodla в настройках моста (аппаратный кодер Jetson).",
  "HUD aç/kapat": "Вкл/выкл HUD",
  "HUD: bağlı dron": "HUD: связанный дрон",
  "HUD: bağlı dron telemetrisi yok": "HUD: нет телеметрии связанного дрона",
  "Henüz kamera yok. Dronun gimbal / EO kamerasını (RTSP ya da RTP) ekleyip görüntüyü taşıyacak köprüyü seçin; köprü (ör. Jetson üzerindeki Hepgo Dron Köprüsü) kaynağı kendi ağında açar ve görüntüyü buraya iter.": "Камер пока нет. Добавьте камеру подвеса / EO дрона (RTSP или RTP) и выберите мост; мост (например, Hepgo Drone Bridge на Jetson) открывает источник в своей сети и передаёт видео сюда.",
