  "Kullanıcı adı ve parolayı adrese değil aşağıya yazın (parola şifreli saklanır).": "Укажите имя и пароль ниже, а не в адресе (пароль хранится зашифрованным).",
  "Köprü (bu görev için)": "Мост (для этого задания)",
  "Köprü seçilmedi": "Мост не выбран",
  "Köprü uygulaması yoksa: Dron Köprüleri sayfasının üstünden Windows ya da Linux / Jetson paketini indirin. Jetson'da: sudo hepgo-kopru eslestir --alan <alan adı> <kod>": "Нет приложения моста? Скачайте пакет Windows или Linux / Jetson вверху страницы «Мосты дронов». На Jetson: sudo hepgo-kopru eslestir --alan <домен> <код>",
  "Köprü çevrim dışı": "Мост не в сети",
  "Köprüde yeniden kodlanır (Jetson: donanım kodlayıcı nvv4l2h264enc; yoksa x264). FPS kaynakla aynıysa ve çözünürlük boşsa kopyalanır.": "Перекодируется на мосту (Jetson: аппаратный кодер nvv4l2h264enc; иначе x264). Копируется, если FPS совпадает с источником и разрешение не задано.",
  "Köprüden tek kare isteniyor…": "Запрос кадра у моста…",
  "Linux / Jetson (arm64)": "Linux / Jetson (arm64)",
  "Linux / Jetson paketi henüz sunucuya yüklenmedi.": "Пакет Linux / Jetson ещё не загружен на сервер.",
  "NVIDIA Jetson Nano / Orin (ya da herhangi bir Ubuntu) üzerinde başsız servis: telemetri köprüsü (UART /dev/ttyTHS1, USB, UDP, TCP) + görüntü köprüsü (RTSP/RTP gimbal kamera → HEPGO). Yalnız dışa doğru bağlanır; 4G / NAT arkasında çalışır.": "Фоновая служба на NVIDIA Jetson Nano / Orin (или любой Ubuntu): мост телеметрии (UART /dev/ttyTHS1, USB, UDP, TCP) + видеомост (камера подвеса RTSP/RTP → HEPGO). Только исходящие соединения; работает за 4G / NAT.",
  "Parola (isteğe bağlı)": "Пароль (необязательно)",
  "Pencere konum/boyutunu varsayılana döndür": "Сбросить положение/размер окна",
  "Pencerede aç": "Открыть в окне",
  "Pencereyi başlığından sürükleyin, köşe/kenar tutamağıyla büyütün (oran korunur). Çift tık: ayrı tarayıcı penceresi. HUD yalnız göstergedir.": "Перетаскивайте окно за заголовок, меняйте размер за углы/края (пропорции сохраняются). Двойной щелчок — отдельное окно. HUD только для отображения.",
  "Pencereyi kapat": "Закрыть окно",
  "RTSP adresi": "Адрес RTSP",
  "SDP (isteğe bağlı)": "SDP (необязательно)",
  "Tanımlı kamera yok (Dron Yönetimi › Kameralar).": "Камеры не заданы (Управление дронами › Камеры).",
  "Tarayıcınız H.265 görüntüyü oynatamıyor; kamerada H.264 seçin ya da köprü ayarında h265 = yeniden_kodla. Şimdilik JPEG anlık görüntü gösteriliyor.": "Браузер не воспроизводит H.265; выберите H.264 на камере или h265 = yeniden_kodla в настройках моста. Пока показываются снимки JPEG.",
